#include <iostream>
#include <string_view>
#include <cstdint>

struct SystemSpec {
    std::string_view domain;
    std::string_view requirement;
    std::uint32_t maxLatencyMicroseconds;
};

int main() {
    // Inspecting fixed-width characteristics standardized since C99 / C++11
    constexpr SystemSpec specs[] = {
        {"Operating System", "Direct kernel memory access", 500},
        {"Embedded ABS", "Sub-millisecond sensor response", 50},
        {"Real-Time Avionics", "Predictable bounded task deadline", 10}
    };

    std::cout << "Evaluation of Critical Domains:\n";
    for (const auto& spec : specs) {
        std::cout << "- Domain: " << spec.domain
                  << " | Target: " << spec.requirement
                  << " | Max Latency: " << spec.maxLatencyMicroseconds << " us\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <string_view>
#include <algorithm>

// Demonstrating Object Technology: modeling an entity via Class
class DeviceComponent {
private:
    std::string name_;
    int batteryPercent_;

public:
    DeviceComponent(std::string_view name, int battery)
        : name_(name), batteryPercent_(std::clamp(battery, 0, 100)) {}

    void consumePower(int amount) {
        // Software reuse: using std::max from standard algorithms
        batteryPercent_ = std::max(0, batteryPercent_ - amount);
    }

    void printStatus() const {
        std::cout << "Device [" << name_ << "] Power: " << batteryPercent_ << "%\n";
    }
};

int main() {
    // Creating software objects representing real-world components
    DeviceComponent controller{"Game Controller", 95};
    DeviceComponent sensor{"Proximity Sensor", 40};

    controller.consumePower(20);
    sensor.consumePower(50);

    controller.printStatus();
    sensor.printStatus();

    return 0;
}
